export const CSS_CERT = "@page{size:A4 landscape;margin:0}*{box-sizing:border-box}body{margin:0;background:#eee;font-family:Georgia,'Times New Roman',serif;color:#1d2d44}.page{width:297mm;height:210mm;padding:11mm;background:#f6f2e8;position:relative}.cert{height:100%;width:100%;position:relative;background:#fbfaf5;border:1.8mm solid #0b2746;outline:.45mm solid #c69b38;outline-offset:-5mm;padding:17mm 23mm 16mm;text-align:center;overflow:hidden}.cert:before,.cert:after{content:'';position:absolute;width:38mm;height:38mm;border-color:#c69b38;opacity:.85}.cert:before{left:7mm;top:7mm;border-left:.8mm solid;border-top:.8mm solid}.cert:after{right:7mm;bottom:7mm;border-right:.8mm solid;border-bottom:.8mm solid}.top{display:flex;align-items:flex-start;justify-content:space-between;position:relative;z-index:2}.logo{width:64mm;max-height:25mm;object-fit:contain;object-position:left center}.ref{font-family:Arial,sans-serif;font-size:7.5pt;letter-spacing:1.8px;color:#647083;text-transform:uppercase;text-align:right;padding-top:3mm}.title{font-size:15pt;letter-spacing:5px;text-transform:uppercase;margin-top:6mm;color:#7c6b4e}.award{font-family:Georgia,'Times New Roman',serif;font-size:31pt;font-weight:700;letter-spacing:2px;text-transform:uppercase;color:#0b2746;margin:4mm 0 3mm}.line{width:120mm;height:.6mm;background:#c69b38;margin:0 auto 5mm}.unit{font-size:25pt;font-weight:700;color:#152f50;margin:1mm 0 5mm}.message{font-size:13pt;line-height:1.65;max-width:205mm;margin:0 auto 3mm}.score{font-family:Arial,sans-serif;font-size:15pt;font-weight:800;color:#a97918;margin-top:4mm}.period{font-family:Arial,sans-serif;font-size:9pt;color:#697586;margin-top:5mm}.cert{display:flex;flex-direction:column}.body{flex:1;min-height:0;display:flex;flex-direction:column;justify-content:space-evenly;align-items:center;padding:0 0 16mm;position:relative;z-index:2}.body>*{margin:0}.grp{display:flex;flex-direction:column;align-items:center;gap:3mm}.grp .award,.grp .line{margin:0}.cert-seal{position:absolute;right:11mm;top:39mm;width:50mm;height:50mm;z-index:3;overflow:visible}.footer{position:absolute;left:23mm;right:23mm;bottom:16mm;display:flex;justify-content:space-between;align-items:flex-end;font-family:Arial,sans-serif;font-size:8.5pt;color:#5e6977}.sig{width:62mm;border-top:.35mm solid #596574;padding-top:2.5mm;text-align:center}.cert-date{position:absolute;left:50%;transform:translateX(-50%);bottom:17mm;font-family:Arial,sans-serif;font-size:7.5pt;color:#7b8490;white-space:nowrap}@media print{body{-webkit-print-color-adjust:exact;print-color-adjust:exact;background:#fff}.page{background:#f6f2e8}}";
